    html+=inputField("corners","Corners",av(wc,"corners"),"number")+inputField("belowFrost","Below frostline",av(fc,"isBelowFrostline"),"checkbox")+inputField("heatedFloor","Heated floor",av(fc,"heatedFloor"),"checkbox");
